import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    q = int(data[1])

    if n == 0 or q == 0:
        return

    arr = [0] * (n + 1)
    for i in range(1, n + 1):
        arr[i] = int(data[1 + i])

    fenwick = [0] * (n + 1)

    def build_fenwick():
        for i in range(1, n + 1):
            j = i + (i & (-i))
            if j <= n:
                fenwick[j] += arr[i]

    def update(i, delta):
        while i <= n:
            fenwick[i] += delta
            i += i & (-i)

    def query(i):
        res = 0
        while i > 0:
            res += fenwick[i]
            i -= i & (-i)
        return res

    build_fenwick()

    output = []
    idx = 1 + n
    for _ in range(q):
        op = int(data[idx])
        idx += 1

        if op == 1:
            x = int(data[idx])
            idx += 1
            y = int(data[idx])
            idx += 1
            delta = y - arr[x]
            arr[x] = y
            update(x, delta)
        elif op == 2:
            x = int(data[idx])
            idx += 1
            output.append(str(query(x)))

    print('\n'.join(output))

if __name__ == "__main__":
    main()
